#!/usr/bin/env bash
# hotpatch.sh — Apply KB auth + quiz normalization fixes
# Run this ON THE SERVER: bash hotpatch.sh
set -e

APP="/home/axisai/axis-frontend"
GREEN='\033[0;32m'; CYAN='\033[0;36m'; RESET='\033[0m'
log() { echo -e "${CYAN}[patch]${RESET} $*"; }
ok()  { echo -e "${GREEN}[  OK  ]${RESET} $*"; }

echo ""
echo "  Axis AI Frontend — KB + Quiz Hotpatch"
echo "  ======================================"
echo ""

# 1. app/api/admin/kb/route.ts
log "Patching app/api/admin/kb/route.ts..."
echo "" | base64 -d > "$APP/app/api/admin/kb/route.ts"
ok "KB route patched"

# 2. app/api/admin/kb/[id]/route.ts
log "Patching app/api/admin/kb/[id]/route.ts..."
mkdir -p "$APP/app/api/admin/kb/[id]"
echo "" | base64 -d > "$APP/app/api/admin/kb/[id]/route.ts"
ok "KB [id] route patched"

# 3. app/api/admin/kb/upload/route.ts
log "Patching app/api/admin/kb/upload/route.ts..."
echo "" | base64 -d > "$APP/app/api/admin/kb/upload/route.ts"
ok "KB upload route patched"

# 4. app/api/content/[contentId]/outputs/route.ts
log "Patching app/api/content/[contentId]/outputs/route.ts..."
echo "" | base64 -d > "$APP/app/api/content/[contentId]/outputs/route.ts"
ok "Outputs route patched (quiz normalization)"

# 5. components/admin/kb-manager.tsx
log "Patching components/admin/kb-manager.tsx..."
echo "" | base64 -d > "$APP/components/admin/kb-manager.tsx"
ok "KB manager component patched"

# 6. components/spaces/creator-dashboard.tsx
log "Patching components/spaces/creator-dashboard.tsx..."
echo "" | base64 -d > "$APP/components/spaces/creator-dashboard.tsx"
ok "Creator dashboard patched"

echo ""
log "Building Next.js..."
cd "$APP"
npm run build 2>&1 | tail -20

echo ""
log "Reloading pm2..."
pm2 reload axis-frontend --update-env
ok "axis-frontend reloaded"

echo ""
echo -e "${GREEN}  ✓ Hotpatch complete!${RESET}"
echo "  Logs: pm2 logs axis-frontend --lines 30 --nostream"
